## GPT disk image with a read-only EROFS root partition. Mount-free, runner
## injected like isobuilder. Initramfs is generated by dracut (default) or Booster.
import std/[os, strutils, times, parsecfg]
import bootconfig, isokernel, isoworkspace, isobuilder

const writableMountsFstab* = staticRead("../data/erofs/writable-mounts.fstab")
  ## Optional fstab block written into the staged rootfs copy.

type
  BootLoader* = enum
    blNone = "none", blGrub = "grub"
  BootArch* = enum
    baAarch64 = "aarch64", baX86_64 = "x86_64"
  InitramfsGenerator* = enum
    igDracut = "dracut", igBooster = "booster"
  ErofsOptions* = object
    rootfs*, output*, name*, workDir*, init*: string
    kernelVersion*, kernelImage*, initramfs*: string
    partLabel*: string
    generator*: InitramfsGenerator
    writableMounts*, clearRootPassword*, overwrite*: bool
    bootloader*: BootLoader
    arch*: string            ## "", aarch64 or x86_64; "" = detect from the rootfs
    espSizeMiB*: int         ## ESP size, 0 = defaultEspSizeMiB
    console*, kernelArgs*: string  ## extra kernel command line (bootloader only)
    verifyGrubDir*: bool     ## runDisk: require GRUB platform files on the host

const defaultPartLabel* = "jsroot"
const espPartLabel* = "JSESP"      ## GPT name and FAT volume label of the ESP
const defaultEspSizeMiB* = 256
const minEspSizeMiB* = 64
const espMarginMiB = 8             ## FAT metadata and slack on top of the payload
const grubModules* = "part_gpt part_msdos fat normal configfile search " &
  "search_label linux echo test gzio all_video efi_gop serial terminal"

proc parseBootLoader*(value: string): BootLoader =
  case value.toLowerAscii
  of "", "none": blNone
  of "grub": blGrub
  else:
    raise newException(ValueError,
        "Unknown bootloader '" & value & "' (use none or grub)")

proc parseBootArch*(value: string): BootArch =
  case value.toLowerAscii
  of "aarch64", "arm64": baAarch64
  of "x86_64", "amd64", "x64": baX86_64
  else:
    raise newException(ValueError,
        "Unsupported architecture '" & value & "' (use aarch64 or x86_64)")

proc grubTarget*(arch: BootArch): string =
  case arch
  of baAarch64: "arm64-efi"
  of baX86_64: "x86_64-efi"

proc efiFallbackName*(arch: BootArch): string =
  ## Removable-media path the firmware tries without any NVRAM entry.
  case arch
  of baAarch64: "BOOTAA64.EFI"
  of baX86_64: "BOOTX64.EFI"

proc grubPlatformDir*(arch: BootArch): string =
  "/usr/lib/grub" / grubTarget(arch)

proc archFromElfHeader*(header: string): BootArch =
  ## ELF e_machine (little endian, offset 18): 0xB7 aarch64, 0x3E x86_64.
  if header.len < 20 or header[0 ..< 4] != "\x7fELF":
    raise newException(ValueError, "Not an ELF file")
  if header[5] != '\x01':
    raise newException(ValueError, "Only little-endian ELF targets are supported")
  case (ord(header[18]) or (ord(header[19]) shl 8))
  of 0xB7: baAarch64
  of 0x3E: baX86_64
  else: raise newException(ValueError, "ELF machine is neither aarch64 nor x86_64")

proc detectRootfsArch*(rootfs, init: string): BootArch =
  ## First ELF among init and common binaries decides the GRUB platform.
  for path in [init, "/usr/bin/jumpstart", "/bin/sh", "/usr/bin/env",
               "/bin/busybox", "/usr/bin/booster"]:
    let resolved = try: resolveRootfsPath(rootfs, path) except ValueError: ""
    if resolved.len == 0 or not fileExists(resolved): continue
    var header = newString(20)
    try:
      let f = open(resolved)
      defer: f.close()
      header.setLen(f.readChars(header))
      return archFromElfHeader(header)
    except ValueError, IOError, OSError: discard
  raise newException(ValueError,
      "Cannot detect the target architecture from the rootfs; pass --arch aarch64|x86_64")

proc parseGenerator*(value: string): InitramfsGenerator =
  case value.toLowerAscii
  of "", "dracut": igDracut
  of "booster": igBooster
  else:
    raise newException(ValueError,
        "Unknown initramfs generator '" & value & "' (use dracut or booster)")

proc validateIsoGenerator*(value: string) =
  ## The live ISO (dmsquash-live, squashfs on iso9660) is dracut-only.
  if parseGenerator(value) == igBooster:
    raise newException(ValueError,
        "Booster cannot build the live ISO layout (no loop/overlay live root support); " &
        "use the 'disk' command for a Booster EROFS image, or keep dracut for ISOs")

proc validatePartLabel*(label: string) =
  ## One safe kernel command-line token that also fits a GPT name.
  if label.len == 0 or label.len > 36:
    raise newException(ValueError, "Partition label must be 1 to 36 characters")
  for ch in label:
    if ch notin {'a'..'z', 'A'..'Z', '0'..'9', '-', '_', '.'}:
      raise newException(ValueError, "Invalid character in partition label")

proc requiredErofsTools*(options: ErofsOptions): seq[string] =
  result = @["cp", "truncate", "mkfs.erofs", "sgdisk", "dd"]
  if options.bootloader == blGrub:
    result.add(@["mkfs.vfat", "mcopy", "grub-mkstandalone"])
  if not dirExists(options.rootfs): result.add("tar")
  if options.initramfs.len == 0:
    case options.generator
    of igBooster: result.add(@["chroot"])  # booster itself must be in the rootfs
    of igDracut: result.add(@["dracut", "depmod", "modprobe"])

proc validateKernelArgs*(value, what: string) =
  ## Space separated tokens that stay safe inside a GRUB linux line.
  for ch in value:
    if ch notin {'a'..'z', 'A'..'Z', '0'..'9', ' ', ',', '.', '_', '-', '+', '=', ':', '/'}:
      raise newException(ValueError, "Invalid character in " & what)

proc validateBootOptions*(options: ErofsOptions) =
  if options.bootloader == blNone:
    if options.arch.len > 0 or options.espSizeMiB != 0 or
        options.console.len > 0 or options.kernelArgs.len > 0:
      raise newException(ValueError,
          "--arch, --espSizeMiB, --console and --kernelArgs require --bootloader=grub")
    return
  if options.arch.len > 0: discard parseBootArch(options.arch)
  if options.espSizeMiB != 0 and options.espSizeMiB < minEspSizeMiB:
    raise newException(ValueError, "--espSizeMiB must be at least " & $minEspSizeMiB)
  validateKernelArgs(options.console, "--console")
  validateKernelArgs(options.kernelArgs, "--kernelArgs")
  for token in options.console.splitWhitespace:
    if token.startsWith("console=") or token[0] == '=':
      raise newException(ValueError,
          "--console takes device names such as ttyAMA0,115200 (krep adds console=)")

proc validateErofsOptions*(options: ErofsOptions) =
  if not dirExists(options.rootfs) and not fileExists(options.rootfs):
    raise newException(ValueError, "Rootfs directory or archive does not exist: " &
        options.rootfs)
  if options.initramfs.len > 0 and not fileExists(options.initramfs):
    raise newException(ValueError, "Initramfs does not exist: " & options.initramfs)
  validateInitPath(options.init)
  validatePartLabel(options.partLabel)
  validateBootOptions(options)
  if options.name.len > 0:
    if options.name[0] == '.' or not options.name.endsWith(".img"):
      raise newException(ValueError, "Image name must be a visible filename ending in .img")
    for ch in options.name:
      if ch notin {'a'..'z', 'A'..'Z', '0'..'9', '-', '_', '.', '+'}:
        raise newException(ValueError, "Image name must be a filename, not a path")
  if dirExists(options.rootfs):
    let source = expandFilename(options.rootfs)
    let workParent = expandFilename(if options.workDir.len >
        0: options.workDir else: getTempDir())
    if workParent == source or workParent.startsWith(source & DirSep):
      raise newException(ValueError, "Workspace must be outside the input rootfs")

proc boosterArgs*(kernelVersion, outputInRoot: string): seq[string] =
  ## Run through `chroot ROOTFS booster ...`: Booster reads /usr/lib/modules/VERSION
  ## of the machine it runs on and has no --modules-dir flag.
  if kernelVersion.len == 0 or outputInRoot.len == 0 or outputInRoot[0] != '/':
    raise newException(ValueError, "Booster requires a kernel version and absolute output path")
  @["build", "--force", "--universal", "--kernel-version", kernelVersion, outputInRoot]

proc rootfsHasBooster*(rootfs: string): bool =
  for path in ["/usr/bin/booster", "/usr/local/bin/booster", "/bin/booster"]:
    if fileExists(resolveRootfsPath(rootfs, path)): return true

proc boosterChrootArgs*(rootfs, kernelVersion, outputInRoot: string): seq[string] =
  @[rootfs, "booster"] & boosterArgs(kernelVersion, outputInRoot)

proc erofsDracutArgs*(kernelVersion, output: string, modulesDir = "",
                      kernelImage = "", configDir = ""): seq[string] =
  ## Plain (non-live) initramfs able to mount an EROFS root partition.
  if kernelVersion.len == 0 or output.len == 0:
    raise newException(ValueError, "Dracut requires a kernel version and output path")
  result = @["--force", "--no-hostonly", "--no-hostonly-cmdline",
    "--modules", "base kernel-modules", "--filesystems", "erofs",
    "--omit", "systemd systemd-initrd", "--kver", kernelVersion]
  if modulesDir.len > 0: result.add(@["--kmoddir", modulesDir])
  if kernelImage.len > 0: result.add(@["--kernel-image", kernelImage])
  if configDir.len > 0: result.add(@["--conf", "/dev/null", "--confdir", configDir])
  result.add(output)

proc mkfsErofsArgs*(label, output, source: string): seq[string] =
  @["-zlz4hc,9", "-L", label, output, source]

proc sgdiskArgs*(image, partLabel: string): seq[string] =
  ## 1 MiB gap (sector 2048), one Linux-filesystem partition to the end.
  @["-o", "-n", "1:2048:0", "-t", "1:8300", "-c", "1:" & partLabel, image]

proc ddArgs*(source, image: string, seekSectors = 2048): seq[string] =
  @["if=" & source, "of=" & image, "bs=512", "seek=" & $seekSectors,
    "conv=notrunc", "status=none"]

proc espSectors*(espMiB: int): int = espMiB * 2048

proc rootStartSector*(espMiB: int): int =
  ## ESP first (USB/firmware friendly), the EROFS root directly after it.
  2048 + espSectors(espMiB)

proc sgdiskBootableArgs*(image, partLabel: string, espMiB: int): seq[string] =
  ## 1: ESP (EF00, JSESP) at sector 2048, 2: EROFS root (8300) to the end.
  @["-o", "-n", "1:2048:+" & $espMiB & "M", "-t", "1:EF00", "-c", "1:" & espPartLabel,
    "-n", "2:" & $rootStartSector(espMiB) & ":0", "-t", "2:8300",
    "-c", "2:" & partLabel, image]

proc mkfsVfatArgs*(image: string): seq[string] =
  @["-F", "32", "-n", espPartLabel, image]

proc mcopyArgs*(espImage: string, sources: seq[string]): seq[string] =
  ## Mount-free copy into the FAT image: -s recursive, -p keep times, -m/-Q bail out.
  @["-i", espImage, "-s", "-p", "-Q"] & sources & @["::/"]

proc grubStandaloneArgs*(arch: BootArch, output, embeddedConfig: string): seq[string] =
  @["--format=" & grubTarget(arch), "--output=" & output, "--modules=" & grubModules,
    "--locales=", "--themes=", "--fonts=", "boot/grub/grub.cfg=" & embeddedConfig]

proc diskSizeBytes*(erofsBytes: int64): int64 =
  ## Partition payload rounded to MiB, plus 4 MiB for the gap and backup GPT.
  let mib = 1024'i64 * 1024
  ((erofsBytes + mib - 1) div mib + 4) * mib

proc diskSizeBytes*(erofsBytes: int64, espMiB: int): int64 =
  diskSizeBytes(erofsBytes) + int64(espMiB) * 1024 * 1024

proc erofsKernelCmdline*(partLabel, init: string, extra = ""): string =
  validatePartLabel(partLabel)
  validateInitPath(init)
  result = "root=PARTLABEL=" & partLabel & " rootfstype=erofs ro init=" & init
  if extra.len > 0: result.add(" " & extra)

proc bootCmdline*(partLabel, init, console, kernelArgs: string): string =
  ## Same base line as the non-bootloader image, plus console=/extra tokens.
  var extra: seq[string]
  for token in console.splitWhitespace: extra.add("console=" & token)
  for token in kernelArgs.splitWhitespace: extra.add(token)
  erofsKernelCmdline(partLabel, init, extra.join(" "))

proc espGrubConfig*(kernelFile, initrdFile, cmdline, console: string,
                    timeout = 3): string =
  ## grub.cfg stored at /boot/grub/grub.cfg on the ESP. Paths are ESP-relative.
  if kernelFile.len == 0 or initrdFile.len == 0 or kernelFile[0] != '/' or
      initrdFile[0] != '/':
    raise newException(ValueError, "GRUB kernel and initrd paths must be absolute")
  validateKernelArgs(cmdline, "kernel command line")
  var serialLines = ""
  for token in console.splitWhitespace:
    if token.startsWith("ttyS") and token.len > 4 and token[4].isDigit:
      let parts = token.split(',')
      let speed = if parts.len > 1 and parts[1].len > 0 and
          parts[1].allCharsInSet(Digits): parts[1] else: "115200"
      serialLines = "serial --unit=" & parts[0][4 .. ^1] & " --speed=" & speed &
        "\nterminal_input serial console\nterminal_output serial console\n"
      break
  result = "set default=0\nset timeout=" & $timeout & "\n" & serialLines &
    "\nmenuentry 'Kreato Linux' --class os {\n" &
    "    insmod gzio\n    insmod part_gpt\n    insmod fat\n" &
    "    linux " & kernelFile & " " & cmdline & "\n" &
    "    initrd " & initrdFile & "\n}\n"

proc espEmbeddedConfig*(): string =
  ## Baked into the EFI binary: find the ESP by FAT label, then load grub.cfg.
  "search --no-floppy --label " & espPartLabel & " --set=root\n" &
    "configfile ($root)/boot/grub/grub.cfg\n"

proc espPayloadMiB*(sizes: seq[int64]): int =
  var total = 0'i64
  for size in sizes: total += size
  int((total + 1048575) div 1048576) + espMarginMiB

proc installWritableMounts*(rootfs: string) =
  ## Append (never replace) the writable-path block to /etc/fstab.
  let path = resolveRootfsPath(rootfs, "/etc/fstab")
  createDir(path.parentDir)
  var existing = if fileExists(path): readFile(path) else: ""
  if existing.len > 0 and not existing.endsWith("\n"): existing.add("\n")
  if writableMountsFstab in existing: return
  writeFile(path, existing & writableMountsFstab)

proc erofsOutputNames*(image: string): tuple[kernel, initramfs, cmdline: string] =
  let stem = image[0 ..< image.len - 4]
  (stem & ".vmlinuz", stem & ".initramfs.img", stem & ".cmdline")

proc assembleErofsImage*(options: ErofsOptions, run: IsoRunner,
                         checkCancelled: proc() {.closure.} = nil): string =
  ## Writes NAME.img (GPT + EROFS) plus NAME.vmlinuz, NAME.initramfs.img and
  ## NAME.cmdline beside it; boot them with a firmware/VMM that loads a kernel
  ## and initrd directly (e.g. qemu -kernel/-initrd, or copy to an ESP).
  validateErofsOptions(options)
  if checkCancelled != nil: checkCancelled()
  createDir(options.output)
  let workspace = createWorkspace(options.workDir)
  defer: cleanupWorkspace(workspace)
  let staged = workspace.path / "rootfs"
  createDir(staged)
  if dirExists(options.rootfs):
    run("cp", @["-a", "--", options.rootfs & "/.", staged])
  else:
    run("tar", @["--extract", "--file", options.rootfs, "--directory", staged,
                  "--numeric-owner", "--same-owner", "--preserve-permissions",
                  "--xattrs", "--xattrs-include=*", "--acls"])
  var metadata = newConfig()
  let releasePath = resolveRootfsPath(staged, "/etc/kreato-release")
  if fileExists(releasePath): metadata = loadConfig(releasePath)
  validateRootfsInit(staged, options.init)
  let kernel = selectKernel(staged, options.kernelVersion, options.kernelImage)
  var bootArch = baAarch64
  var espMiB = 0
  if options.bootloader == blGrub:
    bootArch = if options.arch.len > 0: parseBootArch(options.arch)
               else: detectRootfsArch(staged, options.init)
    espMiB = if options.espSizeMiB > 0: options.espSizeMiB else: defaultEspSizeMiB
    if options.verifyGrubDir and not dirExists(grubPlatformDir(bootArch)):
      raise newException(OSError, "GRUB platform files for " & grubTarget(bootArch) &
          " not found at " & grubPlatformDir(bootArch) & " (install grub-efi-" &
          (if bootArch == baAarch64: "arm64" else: "amd64") & "-bin)")
  let date = metadata.getSectionValue("General", "dateBuilt")
  let name = if options.name.len > 0: options.name
             else: "kreatolinux-" & (if date.len > 0: date else: getDateStr()) &
                 "-erofs-" & kernel.version & ".img"
  result = options.output / name
  let names = erofsOutputNames(result)
  let outputLock = acquireOutputLock(result)
  defer: releaseOutputLock(outputLock)
  for path in [result, names.kernel, names.initramfs, names.cmdline]:
    if (fileExists(path) or dirExists(path) or symlinkExists(path)) and
        not options.overwrite:
      raise newException(IOError, "Output already exists (use --overwrite): " & path)
  if checkCancelled != nil: checkCancelled()
  if options.clearRootPassword: clearStagedRootPassword(staged)
  if options.writableMounts: installWritableMounts(staged)

  let initrd = workspace.path / "initramfs.img"
  if options.initramfs.len > 0:
    copyFile(options.initramfs, initrd)
  else:
    case options.generator
    of igBooster:
      # Generated inside the rootfs copy, then moved out so it is not in the EROFS.
      if not rootfsHasBooster(staged):
        raise newException(ValueError,
            "Booster is not installed in the rootfs (/usr/bin/booster); it runs chrooted " &
            "because it only reads modules from the machine it runs on")
      let inRoot = "/initramfs-krep.img"
      # Booster stats /sys/module; krep mounts nothing, so give it an empty
      # directory in the staged copy and remove it afterwards.
      let sysModule = resolveRootfsPath(staged, "/sys/module")
      let madeSysModule = not dirExists(sysModule)
      createDir(sysModule)
      try:
        run("chroot", boosterChrootArgs(staged, kernel.version, inRoot))
      finally:
        if madeSysModule: removeDir(sysModule)
      let produced = resolveRootfsPath(staged, inRoot)
      if not fileExists(produced):
        raise newException(IOError, "Booster did not produce an initramfs")
      moveFile(produced, initrd)
    of igDracut:
      let emptyConfig = workspace.path / "dracut.conf.d"
      createDir(emptyConfig)
      run("dracut", erofsDracutArgs(kernel.version, initrd, kernel.modulesDir,
          kernel.image, emptyConfig))
  if not fileExists(initrd):
    raise newException(IOError, "No initramfs was generated")

  if checkCancelled != nil: checkCancelled()
  let erofs = workspace.path / "root.erofs"
  run("mkfs.erofs", mkfsErofsArgs(options.partLabel, erofs, staged))
  if not fileExists(erofs):
    raise newException(IOError, "mkfs.erofs did not produce an image")
  let disk = workspace.path / "disk.img"
  var cmdline = erofsKernelCmdline(options.partLabel, options.init)
  if options.bootloader == blGrub:
    cmdline = bootCmdline(options.partLabel, options.init, options.console,
                              options.kernelArgs)
    let kernelName = "vmlinuz-" & kernel.version
    let initrdName = "initramfs-" & kernel.version & ".img"
    let esp = workspace.path / "esp"
    createDir(esp / "EFI" / "BOOT"); createDir(esp / "boot" / "grub")
    let embedded = workspace.path / "grub-embedded.cfg"
    writeFile(embedded, espEmbeddedConfig())
    writeFile(esp / "boot" / "grub" / "grub.cfg", espGrubConfig(
        "/boot/" & kernelName, "/boot/" & initrdName, cmdline, options.console))
    let efi = esp / "EFI" / "BOOT" / efiFallbackName(bootArch)
    run("grub-mkstandalone", grubStandaloneArgs(bootArch, efi, embedded))
    if not fileExists(efi):
      raise newException(IOError, "grub-mkstandalone did not produce " & efiFallbackName(bootArch))
    copyFile(kernel.image, esp / "boot" / kernelName)
    copyFile(initrd, esp / "boot" / initrdName)
    let needed = espPayloadMiB(@[getFileSize(efi), getFileSize(kernel.image),
        getFileSize(initrd)])
    if needed > espMiB:
      raise newException(ValueError, "ESP of " & $espMiB & " MiB is too small for " &
          "kernel, initramfs and GRUB (need about " & $needed & " MiB); raise --espSizeMiB")
    let espImage = workspace.path / "esp.img"
    run("truncate", @["--size", $(int64(espMiB) * 1048576), "--", espImage])
    run("mkfs.vfat", mkfsVfatArgs(espImage))
    run("mcopy", mcopyArgs(espImage, @[esp / "EFI", esp / "boot"]))
    run("truncate", @["--size", $diskSizeBytes(getFileSize(erofs), espMiB), "--", disk])
    run("sgdisk", sgdiskBootableArgs(disk, options.partLabel, espMiB))
    run("dd", ddArgs(espImage, disk))
    run("dd", ddArgs(erofs, disk, rootStartSector(espMiB)))
  else:
    run("truncate", @["--size", $diskSizeBytes(getFileSize(erofs)), "--", disk])
    run("sgdisk", sgdiskArgs(disk, options.partLabel))
    run("dd", ddArgs(erofs, disk))
  publishIso(disk, outputLock, options.overwrite, checkCancelled)
  for (src, dst) in [(kernel.image, names.kernel), (initrd, names.initramfs)]:
    if options.overwrite and fileExists(dst): removeFile(dst)
    copyFile(src, dst)
  writeFile(names.cmdline, cmdline & "\n")
